#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    int j = 0;
    while (j < static_cast<int>(s.size()) && s[j] != 'e') {
        ++j;
    }

    string p = s.substr(0, j);
    string q = s.substr(j + 1);

    int x = stoi(q);

    if (x + 2 >= static_cast<int>(p.size())) {
        int tmp = x + 2 - static_cast<int>(p.size());

        swap(p[0], p[1]);
        string t = p.substr(1);

        while (tmp-- > 0) {
            t += '0';
        }

        cout << t << '\n';
    } else {
        int pos = 1;

        while (x-- > 0) {
            swap(p[pos], p[pos + 1]);
            ++pos;
        }

        pos = static_cast<int>(p.size()) - 1;

        while (pos > 0 && (p[pos] == '0' || p[pos] == '.')) {
            p.erase(p.begin() + pos);
            --pos;
        }

        cout << p << '\n';
    }

    return 0;
}

